export default "import { BADGE_COLOR, VuiBadge, VuiFlexContainer, VuiFlexItem } from \"../../../lib\";\nimport { Subsection } from \"../../components/Subsection\";\n\nconst CUSTOM_COLORS = [\"#1e3a8a\", \"#7c3aed\", \"#f472b6\", \"#facc15\", \"#a7f3d0\", \"#111111\", \"#f5f5f5\"] as const;\n\nexport const BadgeColors = () => {\n  return (\n    <>\n      <Subsection title=\"Large\">\n        <VuiFlexContainer>\n          {BADGE_COLOR.map((color) => (\n            <VuiFlexItem grow={false} key={color}>\n              <VuiBadge size=\"l\" color={color}>\n                Color {color}\n              </VuiBadge>\n            </VuiFlexItem>\n          ))}\n        </VuiFlexContainer>\n      </Subsection>\n\n      <Subsection title=\"Medium\">\n        <VuiFlexContainer>\n          {BADGE_COLOR.map((color) => (\n            <VuiFlexItem grow={false} key={color}>\n              <VuiBadge size=\"m\" color={color}>\n                Color {color}\n              </VuiBadge>\n            </VuiFlexItem>\n          ))}\n        </VuiFlexContainer>\n      </Subsection>\n\n      <Subsection title=\"Small\">\n        <VuiFlexContainer>\n          {BADGE_COLOR.map((color) => (\n            <VuiFlexItem grow={false} key={color}>\n              <VuiBadge size=\"s\" color={color}>\n                Color {color}\n              </VuiBadge>\n            </VuiFlexItem>\n          ))}\n        </VuiFlexContainer>\n      </Subsection>\n\n      <Subsection title=\"Custom hex colors\">\n        <VuiFlexContainer>\n          {CUSTOM_COLORS.map((color) => (\n            <VuiFlexItem grow={false} key={color}>\n              <VuiBadge size=\"m\" color={color}>\n                Color {color}\n              </VuiBadge>\n            </VuiFlexItem>\n          ))}\n        </VuiFlexContainer>\n      </Subsection>\n    </>\n  );\n};\n";