export default "import { useState } from \"react\";\nimport {\n  VuiButtonPrimary,\n  VuiButtonSecondary,\n  VuiModal,\n  VuiSearchSelect,\n  VuiSelect,\n  VuiSpacer,\n  VuiText\n} from \"../../../lib\";\nimport { BiInfoCircle } from \"react-icons/bi\";\n\nconst options = [\n  { value: \"a\", label: \"Caffeine-free\" },\n  { value: \"b\", label: \"Freeze dried\" },\n  { value: \"c\", label: \"Gluten-free\" },\n  { value: \"d\", label: \"Halal\" },\n  { value: \"e\", label: \"High fiber\" },\n  { value: \"f\", label: \"Kosher\" },\n  { value: \"g\", label: \"Lactose-free\" },\n  { value: \"h\", label: \"Low-carb\" },\n  { value: \"i\", label: \"No nuts\" },\n  { value: \"j\", label: \"Non-GMO\" },\n  { value: \"k\", label: \"Sugar-free\" },\n  { value: \"l\", label: \"Vegan\" }\n];\n\nconst sizeOptions = [\n  { text: \"Small\", value: \"s\" },\n  { text: \"Medium\", value: \"m\" },\n  { text: \"Large\", value: \"l\" }\n];\n\nexport const PrimaryModal = () => {\n  const [isOpen, setIsOpen] = useState(false);\n  const [isPopoverOpen, setIsPopoverOpen] = useState(false);\n  const [searchValue, setSearchValue] = useState<string>(\"\");\n  const [size, setSize] = useState<\"s\" | \"m\" | \"l\">(\"s\");\n\n  return (\n    <>\n      <VuiSelect\n        id=\"sizeOptions\"\n        options={sizeOptions}\n        value={size}\n        onChange={(event) => setSize(event.target.value as \"s\" | \"m\" | \"l\")}\n      />\n\n      <VuiSpacer size=\"m\" />\n\n      <VuiButtonPrimary color=\"primary\" onClick={() => setIsOpen(true)}>\n        Open primary modal\n      </VuiButtonPrimary>\n\n      <VuiModal\n        color=\"primary\"\n        isOpen={isOpen}\n        onClose={() => setIsOpen(false)}\n        icon={<BiInfoCircle />}\n        title=\"FYI\"\n        size={size}\n      >\n        <VuiText>\n          <p>I just thought you should know that your modal is showing.</p>\n        </VuiText>\n\n        <VuiSpacer size=\"m\" />\n\n        <VuiSearchSelect\n          title=\"Select all that apply\"\n          isOpen={isPopoverOpen}\n          setIsOpen={setIsPopoverOpen}\n          searchValue={searchValue}\n          setSearchValue={setSearchValue}\n          onSelect={() => undefined}\n          selectedOptions={[]}\n          options={options}\n        >\n          <VuiButtonSecondary color=\"neutral\" size=\"s\">\n            Meal preference\n          </VuiButtonSecondary>\n        </VuiSearchSelect>\n\n        <VuiSpacer size=\"l\" />\n\n        <VuiButtonSecondary color=\"primary\">A no-op button for testing a11y</VuiButtonSecondary>\n      </VuiModal>\n    </>\n  );\n};\n";