export default "import { useState } from \"react\";\nimport { VuiButtonPrimary, VuiFlexContainer, VuiFlexItem, VuiSearchInput } from \"../../../lib\";\nimport { Subsection } from \"../../components/Subsection\";\n\nexport const SearchInput = () => {\n  const [searchValue, setSearchValue] = useState(\"\");\n\n  return (\n    <>\n      <Subsection title=\"Large size\">\n        <VuiFlexContainer alignItems=\"center\">\n          <VuiFlexItem grow={1}>\n            <VuiSearchInput\n              size=\"l\"\n              placeholder=\"Ask a question\"\n              value={searchValue}\n              onChange={(e) => setSearchValue(e.target.value)}\n              onSubmit={(e) => {\n                e.preventDefault();\n                alert(`Submit ${searchValue}`);\n              }}\n            />\n          </VuiFlexItem>\n\n          <VuiFlexItem>\n            <VuiButtonPrimary color=\"primary\" size=\"l\">\n              Search\n            </VuiButtonPrimary>\n          </VuiFlexItem>\n        </VuiFlexContainer>\n      </Subsection>\n\n      <Subsection title=\"Medium size\">\n        <form>\n          <VuiFlexContainer alignItems=\"center\" spacing=\"s\">\n            <VuiFlexItem grow={1}>\n              <VuiSearchInput\n                autoFocus\n                placeholder=\"Ask a question\"\n                value={searchValue}\n                onChange={(e) => setSearchValue(e.target.value)}\n                onSubmit={(e) => {\n                  e.preventDefault();\n                  alert(`Submit ${searchValue}`);\n                }}\n                size=\"m\"\n              />\n            </VuiFlexItem>\n\n            <VuiFlexItem>\n              <VuiButtonPrimary color=\"primary\" size=\"m\">\n                Search\n              </VuiButtonPrimary>\n            </VuiFlexItem>\n          </VuiFlexContainer>\n        </form>\n      </Subsection>\n\n      <Subsection title=\"Small size\">\n        <form>\n          <VuiFlexContainer alignItems=\"center\" spacing=\"xs\">\n            <VuiFlexItem grow={1}>\n              <VuiSearchInput\n                autoFocus\n                placeholder=\"Ask a question\"\n                value={searchValue}\n                onChange={(e) => setSearchValue(e.target.value)}\n                onSubmit={(e) => {\n                  e.preventDefault();\n                  alert(`Submit ${searchValue}`);\n                }}\n                size=\"s\"\n              />\n            </VuiFlexItem>\n\n            <VuiFlexItem>\n              <VuiButtonPrimary color=\"primary\" size=\"s\">\n                Search\n              </VuiButtonPrimary>\n            </VuiFlexItem>\n          </VuiFlexContainer>\n        </form>\n      </Subsection>\n    </>\n  );\n};\n";