export default "import { BiCheck, BiError, BiInfoCircle, BiSolidHand, BiSolidMagicWand, BiStar } from \"react-icons/bi\";\nimport { ICON_COLOR, VuiFlexContainer, VuiFlexItem, VuiIcon, VuiText } from \"../../../lib\";\nimport { Subsection } from \"../../components/Subsection\";\n\nexport const Colors = () => {\n  return (\n    <>\n      <Subsection title=\"Default style\">\n        <VuiFlexContainer>\n          {ICON_COLOR.map((color) => (\n            <VuiFlexItem grow={false} key={color}>\n              <VuiText>\n                <p>Color {color}</p>\n              </VuiText>\n\n              <VuiIcon color={color} size=\"m\">\n                <BiStar />\n              </VuiIcon>\n            </VuiFlexItem>\n          ))}\n        </VuiFlexContainer>\n      </Subsection>\n\n      <Subsection title=\"Enclosed style\">\n        <VuiFlexContainer>\n          {ICON_COLOR.map((color) => (\n            <VuiFlexItem grow={false} key={color}>\n              <VuiText>\n                <p>Color {color}</p>\n              </VuiText>\n\n              <div>\n                <VuiIcon color={color} size=\"m\" type=\"enclosed\">\n                  <BiStar />\n                </VuiIcon>\n              </div>\n            </VuiFlexItem>\n          ))}\n        </VuiFlexContainer>\n      </Subsection>\n\n      <Subsection title=\"Token style\">\n        <VuiFlexContainer>\n          {ICON_COLOR.map((color) => (\n            <VuiFlexItem grow={false} key={color}>\n              <VuiText>\n                <p>Color {color}</p>\n              </VuiText>\n\n              <div>\n                <VuiIcon color={color} size=\"s\" type=\"token\">\n                  <BiStar />\n                </VuiIcon>\n              </div>\n            </VuiFlexItem>\n          ))}\n        </VuiFlexContainer>\n      </Subsection>\n\n      <Subsection title=\"Common tokens\">\n        <VuiFlexContainer>\n          <VuiFlexItem grow={false}>\n            <VuiIcon color=\"danger\" size=\"s\" type=\"token\">\n              <BiSolidHand />\n            </VuiIcon>\n          </VuiFlexItem>\n\n          <VuiFlexItem grow={false}>\n            <VuiIcon color=\"warning\" size=\"s\" type=\"token\">\n              <BiError />\n            </VuiIcon>\n          </VuiFlexItem>\n\n          <VuiFlexItem grow={false}>\n            <VuiIcon color=\"success\" size=\"s\" type=\"token\">\n              <BiCheck />\n            </VuiIcon>\n          </VuiFlexItem>\n\n          <VuiFlexItem grow={false}>\n            <VuiIcon color=\"primary\" size=\"s\" type=\"token\">\n              <BiInfoCircle />\n            </VuiIcon>\n          </VuiFlexItem>\n\n          <VuiFlexItem grow={false}>\n            <VuiIcon color=\"accent\" size=\"s\" type=\"token\">\n              <BiSolidMagicWand />\n            </VuiIcon>\n          </VuiFlexItem>\n        </VuiFlexContainer>\n      </Subsection>\n    </>\n  );\n};\n";